package br.com.admeclesial.application.catequese;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.domain.catequese.*; import br.com.admeclesial.infrastructure.persistence.catequese.*; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.time.LocalDate; import java.util.*;
@Service public class TurmaCatequeseApplicationService {
 @Autowired private SegurancaOrganizacaoService seguranca;
 private final TurmaCatequeseRepository repository; private final EtapaCatequeseRepository etapaRepository; private final OrganizacaoEclesialRepository organizacaoRepository;
 public TurmaCatequeseApplicationService(TurmaCatequeseRepository r,EtapaCatequeseRepository e,OrganizacaoEclesialRepository o){repository=r;etapaRepository=e;organizacaoRepository=o;}
 @Transactional public TurmaCatequeseResponse criar(TurmaCatequeseRequest r){validarAcesso(r.organizacaoEclesialUuid());validarPeriodo(r.dataInicio(),r.dataFim());var etapa=etapaRepository.findByUuid(r.etapaCatequeseUuid()).orElseThrow(()->new CatequeseBusinessException("Etapa de catequese não encontrada."));var org=organizacaoRepository.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new CatequeseBusinessException("Organização eclesial não encontrada."));if(!org.isAtivo())throw new CatequeseBusinessException("A organização eclesial está inativa.");if(!etapa.isAtivo())throw new CatequeseBusinessException("A etapa de catequese está inativa.");if(etapa.getCatequese().getOrganizacaoEclesial().getId().longValue()!=org.getId().longValue())throw new CatequeseBusinessException("A turma deve pertencer à mesma organização da catequese.");var e=new TurmaCatequese();e.setEtapaCatequese(etapa);e.setOrganizacaoEclesial(org);e.setNome(r.nome().trim());e.setAno(r.ano());e.setTurno(r.turno());e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setCapacidade(r.capacidade());e.setLocal(text(r.local()));e.setStatus(r.status()==null?StatusCatequese.PLANEJADA:r.status());e.setObservacao(text(r.observacao()));return toResponse(repository.save(e));}
 @Transactional
 public TurmaCatequeseResponse atualizar(UUID uuid, TurmaCatequeseRequest r){var e=repository.findByUuid(uuid).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(e.getOrganizacaoEclesial().getUuid());validarAcesso(r.organizacaoEclesialUuid());validarPeriodo(r.dataInicio(),r.dataFim());var etapa=etapaRepository.findByUuid(r.etapaCatequeseUuid()).orElseThrow(()->new CatequeseBusinessException("Etapa de catequese não encontrada."));var org=organizacaoRepository.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new CatequeseBusinessException("Organização eclesial não encontrada."));if(!org.isAtivo())throw new CatequeseBusinessException("A organização eclesial está inativa.");if(!etapa.isAtivo())throw new CatequeseBusinessException("A etapa de catequese está inativa.");if(etapa.getCatequese().getOrganizacaoEclesial().getId().longValue()!=org.getId().longValue())throw new CatequeseBusinessException("A turma deve pertencer à mesma organização da catequese.");e.setEtapaCatequese(etapa);e.setOrganizacaoEclesial(org);e.setNome(r.nome().trim());e.setAno(r.ano());e.setTurno(r.turno());e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setCapacidade(r.capacidade());e.setLocal(text(r.local()));e.setStatus(r.status()==null?StatusCatequese.PLANEJADA:r.status());e.setObservacao(text(r.observacao()));return toResponse(repository.save(e));}
 @Transactional(readOnly=true) public TurmaCatequeseResponse buscar(UUID uuid){var e=repository.findByUuid(uuid).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(e.getOrganizacaoEclesial().getUuid());return toResponse(e);}
 @Transactional(readOnly=true) public List<TurmaCatequeseResponse> listar(){var a=seguranca==null?null:seguranca.organizacoesAutorizadas();return repository.findAllByOrderByAnoDescNomeAsc().stream().filter(e->a==null||a.contains(e.getOrganizacaoEclesial().getUuid())).map(this::toResponse).toList();}
 @Transactional(readOnly=true) public List<TurmaCatequeseResponse> listarPorEtapa(UUID uuid){var e=etapaRepository.findByUuid(uuid).orElseThrow(()->new CatequeseBusinessException("Etapa de catequese não encontrada."));validarAcesso(e.getCatequese().getOrganizacaoEclesial().getUuid());return repository.findAllByEtapaCatequeseIdOrderByNomeAsc(e.getId()).stream().map(this::toResponse).toList();}
 private TurmaCatequeseResponse toResponse(TurmaCatequese e){var etapa=e.getEtapaCatequese();var org=e.getOrganizacaoEclesial();return new TurmaCatequeseResponse(e.getUuid(),etapa.getUuid(),etapa.getNome(),org.getUuid(),org.getNome(),e.getNome(),e.getAno(),e.getTurno(),e.getDataInicio(),e.getDataFim(),e.getCapacidade(),e.getLocal(),e.getStatus(),e.getObservacao());}
 private void validarPeriodo(LocalDate i,LocalDate f){if(f!=null&&i==null)throw new CatequeseBusinessException("Data inicial é obrigatória quando a data final for informada.");if(i!=null&&f!=null&&f.isBefore(i))throw new CatequeseBusinessException("Data final não pode ser anterior à data inicial.");}
 private String text(String v){return StringUtils.hasText(v)?v.trim():null;}

 private void validarAcesso(java.util.UUID uuid){if(seguranca!=null)seguranca.validarAcesso(uuid);}
}
